pub fn width_bits() -> Result<usize, String> {
    let text = std::fs::read_to_string("/app/ribcards/LAYOUT.txt")
        .map_err(|e| format!("layout: {e}"))?;
    let mut maximum = None::<u32>;

    for (index, line) in text.lines().enumerate() {
        let raw = line.trim();
        if raw.is_empty() || raw.starts_with('#') {
            continue;
        }
        let parts: Vec<&str> = raw.split_whitespace().collect();
        if parts.len() != 3 {
            return Err(format!("layout line {}", index + 1));
        }
        let pos: u32 = parts[1].parse().map_err(|_| format!("layout line {}", index + 1))?;
        let width: u32 = parts[2].parse().map_err(|_| format!("layout line {}", index + 1))?;
        if width == 0 || width > 32 {
            return Err(format!("layout line {}", index + 1));
        }
        let end = pos.checked_add(width).ok_or_else(|| format!("layout line {}", index + 1))?;
        maximum = Some(maximum.map_or(end, |old| old.max(end)));
    }

    maximum.map(|v| v as usize).ok_or_else(|| "empty layout".to_string())
}
