use crate::pull;
use crate::tally;
use std::fs;
use std::io::ErrorKind;
use std::path::Path;

fn clear(path: &Path) -> bool {
    match fs::remove_file(path) {
        Ok(()) => true,
        Err(e) if e.kind() == ErrorKind::NotFound => true,
        Err(e) => {
            eprintln!("remove output: {e}");
            false
        }
    }
}

pub fn rib_c() -> i32 {
    let dest = Path::new("/app/blotbay/rows.json");
    let temp = Path::new("/app/blotbay/rows.json.tmp");
    if !clear(dest) {
        return 1;
    }
    let _ = clear(temp);

    let width = match tally::width_bits() {
        Ok(v) => v,
        Err(e) => {
            eprintln!("{e}");
            return 1;
        }
    };
    let buf = match fs::read("/app/quaybag/night.bin") {
        Ok(v) => v,
        Err(e) => {
            eprintln!("input: {e}");
            return 1;
        }
    };
    if buf.len().saturating_mul(8) < width {
        eprintln!("input is shorter than layout width");
        return 1;
    }

    let (a, b, c, d, e, f) = pull::dump(&buf);
    let body = format!(
        "{{\"kind\":{},\"lane\":{},\"mode\":{},\"welt\":{},\"tail\":{},\"mark\":{}}}\n",
        a, b, c, d, e, f
    );
    if let Some(parent) = dest.parent() {
        if let Err(e) = fs::create_dir_all(parent) {
            eprintln!("output directory: {e}");
            return 1;
        }
    }
    if let Err(e) = fs::write(temp, body).and_then(|_| fs::rename(temp, dest)) {
        eprintln!("output: {e}");
        let _ = clear(temp);
        let _ = clear(dest);
        return 1;
    }
    0
}
